using System;using System.Collections.Generic;using UnityEngine;
namespace SkyIsland {
 [Serializable] public class GroundItemState {public string item;public int count;public Vector3 position;public bool Valid()=>BackpackRules.Known(item)&&count>0&&count<=BackpackRules.Limit(item)&&!float.IsNaN(position.x)&&!float.IsInfinity(position.x)&&!float.IsNaN(position.y)&&!float.IsInfinity(position.y)&&!float.IsNaN(position.z)&&!float.IsInfinity(position.z)&&Mathf.Abs(position.x)<10000&&Mathf.Abs(position.y)<10000&&Mathf.Abs(position.z)<10000;}
 [Serializable] public class ItemStack {public string item;public int count;public ItemStack(){}public ItemStack(string item,int count){this.item=item;this.count=count;}}
 [Serializable] public class BackpackState {public int version=1;public List<ItemStack> slots=new List<ItemStack>();public ItemStack cursor=new ItemStack();public List<ItemStack> overflow=new List<ItemStack>();}
 public static class BackpackRules {
  public const int Main=27,Hotbar=8,Size=35;
  public static readonly string[] Items={"wood","stone","food","panel","bench","axe","pickaxe"};
  public static bool Known(string item)=>Array.IndexOf(Items,item)>=0;
  public static int Limit(string item)=>item=="axe"||item=="pickaxe"?1:64;
  public static string Name(string item)=>item=="wood"?"木材":item=="stone"?"石料":item=="food"?"食材":item=="panel"?"木板":item=="bench"?"工作台":item=="axe"?"木斧":item=="pickaxe"?"木镐":"空手";
  public static BackpackState Empty(){var b=new BackpackState();for(int i=0;i<Size;i++)b.slots.Add(new ItemStack());return b;}
  public static BackpackState Copy(BackpackState b)=>JsonUtility.FromJson<BackpackState>(JsonUtility.ToJson(b));
  static bool ValidStack(ItemStack s,bool overflow=false)=>s!=null&&s.count>=0&&(s.count==0?string.IsNullOrEmpty(s.item):Known(s.item)&&s.count<=(overflow?1000000:Limit(s.item)));
  public static bool Valid(BackpackState b){if(b==null||b.version!=1||b.slots==null||b.slots.Count!=Size||b.overflow==null||b.overflow.Count>Items.Length||!ValidStack(b.cursor))return false;foreach(var s in b.slots)if(!ValidStack(s))return false;var seen=new HashSet<string>();foreach(var s in b.overflow)if(!ValidStack(s,true)||s.count<=0||!seen.Add(s.item))return false;return true;}
  static void Clean(ItemStack s){if(s.count==0)s.item=null;}
  public static int Count(BackpackState b,string item){int total=b.cursor.item==item?b.cursor.count:0;foreach(var s in b.slots)if(s.item==item)total+=s.count;return total;}
  public static int Capacity(BackpackState b,string item){if(!Known(item))return 0;int capacity=0;foreach(var s in b.slots)if(s.count==0||s.item==item)capacity+=Limit(item)-s.count;return capacity;}
  static IEnumerable<int> Preferred(){for(int i=Main;i<Size;i++)yield return i;for(int i=0;i<Main;i++)yield return i;}
  public static int AddPartial(BackpackState b,string item,int amount){if(!Known(item)||amount<=0)return amount;int remaining=amount;foreach(var s in b.slots)if(s.item==item&&s.count<Limit(item)){int n=Math.Min(remaining,Limit(item)-s.count);s.count+=n;remaining-=n;if(remaining==0)return 0;}foreach(int index in Preferred()){var s=b.slots[index];if(s.count!=0)continue;int n=Math.Min(remaining,Limit(item));s.item=item;s.count=n;remaining-=n;if(remaining==0)break;}return remaining;}
  public static bool Add(BackpackState b,string item,int amount){if(amount<=0||Capacity(b,item)<amount)return false;AddPartial(b,item,amount);return true;}
  public static bool Take(BackpackState b,string item,int amount,int preferred=-1){if(amount<0||Count(b,item)<amount)return false;if(preferred>=0&&preferred<Size&&b.slots[preferred].item==item){var first=b.slots[preferred];int n=Math.Min(first.count,amount);first.count-=n;amount-=n;Clean(first);}if(amount==0)return true;foreach(var s in b.slots)if(s.item==item){int n=Math.Min(s.count,amount);s.count-=n;amount-=n;Clean(s);if(amount==0)return true;}if(b.cursor.item==item){b.cursor.count-=amount;Clean(b.cursor);}return true;}
  public static bool Click(BackpackState b,int index,bool right){if(index<0||index>=Size)return false;var slot=b.slots[index];var hand=b.cursor;
   if(hand.count==0){if(slot.count==0)return false;int n=right?(slot.count+1)/2:slot.count;hand.item=slot.item;hand.count=n;slot.count-=n;Clean(slot);return true;}
   if(slot.count==0||slot.item==hand.item){int n=Math.Min(right?1:hand.count,Limit(hand.item)-slot.count);if(n<=0)return false;slot.item=hand.item;slot.count+=n;hand.count-=n;Clean(hand);return true;}
   if(right)return false;var old=slot.item;int count=slot.count;slot.item=hand.item;slot.count=hand.count;hand.item=old;hand.count=count;return true;
  }
  public static bool QuickMove(BackpackState b,int index){if(index<0||index>=Size||b.slots[index].count==0)return false;var source=b.slots[index];int start=index<Main?Main:0,end=index<Main?Size:Main,before=source.count;
   for(int pass=0;pass<2;pass++)for(int i=start;i<end&&source.count>0;i++){var target=b.slots[i];if(pass==0?target.item!=source.item||target.count==0:target.count!=0)continue;int n=Math.Min(source.count,Limit(source.item)-target.count);target.item=source.item;target.count+=n;source.count-=n;}Clean(source);return source.count!=before;
  }
  public static bool ReturnCursor(BackpackState b){if(b.cursor.count==0)return true;if(!Add(b,b.cursor.item,b.cursor.count))return false;b.cursor=new ItemStack();return true;}
  public static string Selected(SurvivalState state){if(state==null)return "";if(state.bag!=null&&Valid(state.bag)){var s=state.bag.slots[Main+state.selectedSlot];return s.count>0?s.item:"";}return state.selectedSlot==1&&state.axes>0?"axe":state.selectedSlot==2&&state.pickaxes>0?"pickaxe":state.selectedSlot==3&&state.benches>0?"bench":state.selectedSlot==7?"panel":"";}
 }
 public static class BackpackBridge {
  public static int Get(HexIsland island,SurvivalState state,string kind)=>kind=="wood"?island.Wood:kind=="stone"?island.Stone:kind=="food"?state.food:kind=="panel"?state.panels:kind=="bench"?state.benches:kind=="axe"?state.axes:kind=="pickaxe"?state.pickaxes:-1;
  public static void Set(HexIsland island,SurvivalState state,string kind,int value){if(kind=="wood")island.Wood=value;else if(kind=="stone")island.Stone=value;else if(kind=="food")state.food=value;else if(kind=="panel")state.panels=value;else if(kind=="bench")state.benches=value;else if(kind=="axe")state.axes=value;else if(kind=="pickaxe")state.pickaxes=value;}
  public static void Apply(HexIsland island,SurvivalState state){foreach(var kind in BackpackRules.Items)Set(island,state,kind,BackpackRules.Count(state.bag,kind));}
  public static bool Sync(HexIsland island,SurvivalState state){if(state.bag==null)return true;if(!BackpackRules.Valid(state.bag))return false;var copy=BackpackRules.Copy(state.bag);foreach(var kind in BackpackRules.Items){int difference=Get(island,state,kind)-BackpackRules.Count(copy,kind);if(difference<0&&!BackpackRules.Take(copy,kind,-difference,27+state.selectedSlot))return false;}foreach(var kind in BackpackRules.Items){int difference=Get(island,state,kind)-BackpackRules.Count(copy,kind);if(difference>0&&!BackpackRules.Add(copy,kind,difference))return false;}state.bag=copy;return true;}
  public static void Migrate(HexIsland island,SurvivalState state){if(state.bag!=null&&BackpackRules.Valid(state.bag)){if(!Sync(island,state))throw new InvalidOperationException("BAG_TOTAL_MISMATCH");return;}var totals=new Dictionary<string,int>();foreach(var kind in BackpackRules.Items)totals[kind]=Math.Max(0,Get(island,state,kind));state.bag=BackpackRules.Empty();string[] legacy={"","axe","pickaxe","bench","wood","stone","food","panel"};for(int i=1;i<legacy.Length;i++){string kind=legacy[i];int n=Math.Min(totals[kind],BackpackRules.Limit(kind));if(n>0){state.bag.slots[BackpackRules.Main+i]=new ItemStack(kind,n);totals[kind]-=n;}}foreach(var kind in BackpackRules.Items){int remaining=BackpackRules.AddPartial(state.bag,kind,totals[kind]);if(remaining>0)state.bag.overflow.Add(new ItemStack(kind,remaining));}Apply(island,state);}
  public static bool Edit(HexIsland island,SurvivalState state,Func<BackpackState,bool> edit,Func<bool> save){if(!Sync(island,state))return false;var before=BackpackRules.Copy(state.bag);if(!edit(state.bag))return false;Apply(island,state);bool ok;try{ok=save();}catch{ok=false;}if(ok)return true;state.bag=before;Apply(island,state);return false;}
  public static bool Fits(HexIsland island,SurvivalState state,Dictionary<string,int> changes){foreach(var pair in changes)if(!BackpackRules.Known(pair.Key)||Get(island,state,pair.Key)+(long)pair.Value<0||Get(island,state,pair.Key)+(long)pair.Value>1000000)return false;if(state.bag==null)return true;var old=state.bag;try{if(!Sync(island,state))return false;var copy=BackpackRules.Copy(state.bag);foreach(var pair in changes)if(pair.Value<0&&!BackpackRules.Take(copy,pair.Key,-pair.Value,27+state.selectedSlot))return false;foreach(var pair in changes)if(pair.Value>0&&!BackpackRules.Add(copy,pair.Key,pair.Value))return false;return true;}finally{state.bag=old;}}
 }
}
